-- Exact dependent column types, nullability, and enum members. A failure names the missing/mismatched column.
SET @schema_check=(SELECT COUNT(*)=1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='Devices' AND column_name='device_id' AND DATA_TYPE='int' AND COLUMN_TYPE NOT LIKE '%unsigned%' AND IS_NULLABLE='NO');
CALL bank_lab.sp_assert_true(DATABASE(),'contract Devices.device_id',@schema_check,'Missing or incompatible Devices.device_id (int; nullable NO)');
SET @schema_check=(SELECT COUNT(*)=1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='Devices' AND column_name='customer_id' AND DATA_TYPE='int' AND COLUMN_TYPE NOT LIKE '%unsigned%' AND IS_NULLABLE='NO');
